use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Encodes some bytes into a mutable slice of bytes using lowercase characters."] # [doc = ""] # [doc = " The output buffer, has to be able to hold exactly `input.len() * 2` bytes,"] # [doc = " otherwise this function will return an error."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " # use hex::FromHexError;"] # [doc = " # fn main() -> Result<(), FromHexError> {"] # [doc = " let mut bytes = [0u8; 4 * 2];"] # [doc = ""] # [doc = " hex::encode_to_slice(b\"kiwi\", &mut bytes)?;"] # [doc = " assert_eq!(&bytes, b\"6b697769\");"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " If the buffer is too large, an error is returned:"] # [doc = ""] # [doc = " ```"] # [doc = " use hex::FromHexError;"] # [doc = " # fn main() -> Result<(), FromHexError> {"] # [doc = " let mut bytes = [0_u8; 5 * 2];"] # [doc = ""] # [doc = " assert_eq!(hex::encode_to_slice(b\"kiwi\", &mut bytes), Err(FromHexError::InvalidStringLength));"] # [doc = ""] # [doc = " // you can do this instead:"] # [doc = " hex::encode_to_slice(b\"kiwi\", &mut bytes[..4 * 2])?;"] # [doc = " assert_eq!(&bytes, b\"6b697769\\0\\0\");"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn encode_to_slice < T : AsRef < [u8] > > (input : T , output : & mut [u8]) -> Result < () , FromHexError > { encode_to_slice_inner (input . as_ref () , output , HEX_CHARS_LOWER) }